DROP TABLE IF EXISTS `h_house`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `h_house` (
  `house_id` bigint NOT NULL AUTO_INCREMENT COMMENT '房源 ID',
  `agent_id` bigint NOT NULL COMMENT '中介 ID',
  `house_title` varchar(200) NOT NULL COMMENT '房源标题',
  `house_address` varchar(500) NOT NULL COMMENT '详细地址',
  `house_province` varchar(50) DEFAULT NULL COMMENT '省份',
  `house_city` varchar(50) DEFAULT NULL COMMENT '城市',
  `house_district` varchar(50) DEFAULT NULL COMMENT '区县',
  `house_community` varchar(100) DEFAULT NULL COMMENT '小区名称',
  `house_area` decimal(10,2) DEFAULT NULL COMMENT '面积 (平方米)',
  `house_price` decimal(15,2) DEFAULT NULL COMMENT '售价 (万元)',
  `house_unit_price` decimal(10,2) DEFAULT NULL COMMENT '单价 (元/平米)',
  `house_type` varchar(20) DEFAULT NULL COMMENT '户型',
  `house_layout` varchar(50) DEFAULT NULL COMMENT '户型结构',
  `house_floor` varchar(20) DEFAULT NULL COMMENT '楼层',
  `house_total_floor` int DEFAULT NULL COMMENT '总楼层',
  `house_building_year` int DEFAULT NULL COMMENT '建筑年代',
  `house_orientation` varchar(20) DEFAULT NULL COMMENT '朝向',
  `house_decoration` varchar(20) DEFAULT NULL COMMENT '装修情况',
  `house_property_type` varchar(20) DEFAULT NULL COMMENT '房屋类型',
  `house_property_fee` decimal(10,2) DEFAULT NULL COMMENT '物业费',
  `house_elevator` tinyint DEFAULT NULL COMMENT '是否有电梯',
  `house_heating` tinyint DEFAULT NULL COMMENT '供暖',
  `house_description` text COMMENT '房源描述',
  `house_images` json DEFAULT NULL COMMENT '房源图片 (JSON 数组)',
  `house_video_url` varchar(500) DEFAULT NULL COMMENT '房源视频 URL',
  `house_facilities` json DEFAULT NULL COMMENT '配套设施 (JSON 数组)',
  `house_tags` varchar(500) DEFAULT NULL COMMENT '标签',
  `house_status` tinyint DEFAULT '0' COMMENT '房源状态：0-未发布 1-已发布 2-已成交 3-已下架',
  `house_view_count` int DEFAULT '0' COMMENT '浏览次数',
  `house_favorite_count` int DEFAULT '0' COMMENT '收藏次数',
  `house_audit_status` tinyint DEFAULT '0' COMMENT '审核状态：0-待审核 1-已通过 2-已拒绝',
  `house_reject_reason` varchar(500) DEFAULT NULL COMMENT '拒绝原因',
  `house_create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `house_update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`house_id`),
  KEY `idx_agent_id` (`agent_id`),
  KEY `idx_house_address` (`house_address`),
  KEY `idx_house_price` (`house_price`),
  KEY `idx_house_district` (`house_district`),
  KEY `idx_house_status` (`house_status`),
  KEY `idx_house_audit_status` (`house_audit_status`),
  KEY `idx_house_create_time` (`house_create_time`),
  CONSTRAINT `h_house_ibfk_1` FOREIGN KEY (`agent_id`) REFERENCES `sys_agent` (`agent_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=90 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='房源表';
