--
-- Table structure for table `h_message`
--

DROP TABLE IF EXISTS `h_message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `h_message` (
  `message_id` bigint NOT NULL AUTO_INCREMENT COMMENT '消息 ID',
  `message_sender_id` bigint NOT NULL COMMENT '发送者 ID',
  `message_sender_type` tinyint NOT NULL COMMENT '发送者类型：1-管理员 2-中介 3-客户',
  `message_receiver_id` bigint NOT NULL COMMENT '接收者 ID',
  `message_receiver_type` tinyint NOT NULL COMMENT '接收者类型：1-管理员 2-中介 3-客户',
  `message_type` tinyint NOT NULL DEFAULT '2' COMMENT '娑堟伅绫诲瀷锛?-绯荤粺閫氱煡 2-鐢ㄦ埛娑堟伅',
  `message_content_type` varchar(20) NOT NULL DEFAULT 'TEXT' COMMENT '内容类型：TEXT-文本 IMAGE-图片',
  `message_scene` varchar(50) NOT NULL DEFAULT 'CHAT' COMMENT '娑堟伅鍦烘櫙锛欳HAT/VIEWING_REQUEST/VIEWING_REVIEW_INVITE/TRANSACTION_CREATED',
  `message_title` varchar(200) NOT NULL COMMENT '消息标题',
  `message_content` text NOT NULL COMMENT '消息内容',
  `message_house_id` bigint DEFAULT NULL COMMENT '鍏宠仈鎴挎簮 ID',
  `message_viewing_id` bigint DEFAULT NULL COMMENT '鍏宠仈甯︾湅 ID',
  `message_is_read` tinyint DEFAULT '0' COMMENT '是否已读：0-未读 1-已读',
  `message_read_time` datetime DEFAULT NULL COMMENT '阅读时间',
  `message_create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `message_update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`message_id`),
  KEY `idx_sender` (`message_sender_id`,`message_sender_type`),
  KEY `idx_receiver` (`message_receiver_id`,`message_receiver_type`),
  KEY `idx_is_read` (`message_is_read`),
  KEY `idx_create_time` (`message_create_time`),
  KEY `idx_message_scene` (`message_scene`),
  KEY `idx_message_house_id` (`message_house_id`),
  KEY `idx_message_viewing_id` (`message_viewing_id`),
  CONSTRAINT `fk_message_house_id` FOREIGN KEY (`message_house_id`) REFERENCES `h_house` (`house_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_message_viewing_id` FOREIGN KEY (`message_viewing_id`) REFERENCES `h_viewing` (`viewing_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=115 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='消息通知表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `h_message`
--

LOCK TABLES `h_message` WRITE;
/*!40000 ALTER TABLE `h_message` DISABLE KEYS */;
