--
-- Table structure for table `h_review`
--

DROP TABLE IF EXISTS `h_review`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `h_review` (
  `review_id` bigint NOT NULL AUTO_INCREMENT COMMENT '评价 ID',
  `transaction_id` bigint DEFAULT NULL COMMENT '交易 ID（可选，允许为空）',
  `viewing_id` bigint DEFAULT NULL COMMENT '带看 ID',
  `house_id` bigint DEFAULT NULL COMMENT '房源 ID',
  `agent_id` bigint DEFAULT NULL COMMENT '中介 ID',
  `customer_id` bigint NOT NULL COMMENT '客户 ID',
  `review_target_type` tinyint NOT NULL COMMENT '评价对象：1-房源 2-中介 3-整体',
  `review_rating` tinyint NOT NULL COMMENT '评分 (1-5)',
  `review_content` text COMMENT '评价内容',
  `review_images` json DEFAULT NULL COMMENT '评价图片 (JSON 数组)',
  `review_reply_content` varchar(500) DEFAULT NULL COMMENT '回复内容',
  `review_reply_time` datetime DEFAULT NULL COMMENT '回复时间',
  `review_is_show` tinyint DEFAULT '1' COMMENT '是否显示：0-隐藏 1-显示',
  `review_create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `review_update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`review_id`),
  KEY `idx_transaction_id` (`transaction_id`),
  KEY `idx_house_id` (`house_id`),
  KEY `idx_agent_id` (`agent_id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_review_target_type` (`review_target_type`),
  KEY `idx_viewing_id` (`viewing_id`),
  CONSTRAINT `fk_review_transaction` FOREIGN KEY (`transaction_id`) REFERENCES `h_transaction` (`transaction_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_review_viewing_id` FOREIGN KEY (`viewing_id`) REFERENCES `h_viewing` (`viewing_id`) ON DELETE SET NULL,
  CONSTRAINT `h_review_ibfk_2` FOREIGN KEY (`house_id`) REFERENCES `h_house` (`house_id`) ON DELETE SET NULL,
  CONSTRAINT `h_review_ibfk_3` FOREIGN KEY (`agent_id`) REFERENCES `sys_agent` (`agent_id`) ON DELETE SET NULL,
  CONSTRAINT `h_review_ibfk_4` FOREIGN KEY (`customer_id`) REFERENCES `sys_customer` (`customer_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='评价表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `h_review`
--

LOCK TABLES `h_review` WRITE;
/*!40000 ALTER TABLE `h_review` DISABLE KEYS */;
INSERT INTO `h_review` VALUES (1,NULL,NULL,1,1,1,1,5,'一个小目标而已，拿下拿下。','[]',NULL,NULL,1,'2026-04-03 12:04:20','2026-04-17 18:23:07'),(2,NULL,NULL,2,4,2,1,4,'房子很不错，采光好，通风也不错，就是价格稍微有点高。张三经理服务态度很好，讲解很详细。',NULL,NULL,NULL,1,'2026-03-26 23:36:58','2026-04-03 23:36:58'),(3,NULL,NULL,6,5,2,1,5,'学区房确实稀缺，户型方正，周边配套完善。虽然总价高但值得投资。',NULL,NULL,NULL,1,'2026-03-28 23:36:58','2026-04-03 23:36:58'),(4,NULL,NULL,4,5,3,1,4,'LOFT 公寓很适合年轻人，交通便利，周边商业配套成熟。',NULL,NULL,NULL,1,'2026-04-01 23:36:58','2026-04-03 23:36:58'),(5,NULL,1,11,6,4,2,5,'带看节奏很稳，讲解专业，后续跟进也很及时。',NULL,NULL,NULL,1,'2025-11-20 21:43:07','2026-04-14 21:43:07'),(6,NULL,NULL,12,6,5,1,4,'房源整体不错，地铁和商业配套都很方便。',NULL,NULL,NULL,1,'2026-04-03 21:43:07','2026-04-14 21:43:07'),(7,NULL,3,16,8,6,2,5,'服务细致，能把价格和板块逻辑讲得很清楚。',NULL,NULL,NULL,1,'2026-01-24 21:43:07','2026-04-14 21:43:07'),(8,NULL,NULL,18,8,8,1,5,'核心地段保值性强，房源状态也很好。',NULL,NULL,NULL,1,'2026-03-11 21:43:07','2026-04-14 21:43:07'),(9,NULL,4,14,6,7,2,4,'沟通顺畅，安排时间灵活。',NULL,NULL,NULL,1,'2026-02-17 21:43:07','2026-04-14 21:43:07'),(10,NULL,12,19,7,6,2,4,'性价比分析到位，适合预算型客户参考。',NULL,NULL,NULL,1,'2026-04-13 21:43:07','2026-04-14 21:43:07'),(11,NULL,NULL,19,7,6,1,4,'户型实用，适合作为通勤盘备选。',NULL,NULL,NULL,1,'2026-04-13 21:43:07','2026-04-14 21:43:07'),(12,NULL,6,20,9,9,2,5,'贷款流程说明清楚，推进效率高。',NULL,NULL,NULL,1,'2026-04-09 21:43:07','2026-04-14 21:43:07'),(13,NULL,NULL,23,1,1,1,5,'房源信息真实可靠，中介认真介绍房源，非常仔细、专业。','[]',NULL,NULL,1,'2026-04-16 14:37:34','2026-04-16 14:37:34'),(14,NULL,NULL,24,1,1,2,5,'房源真实可靠，中介也细心带看，非常好','[]',NULL,NULL,1,'2026-04-16 21:34:37','2026-04-16 21:34:37'),(15,NULL,NULL,24,1,1,1,5,'一看这个房子就好啊👍👍，就是感觉有点不尊重，放个QQ号再上面，价格都不放。','[]',NULL,NULL,1,'2026-04-17 19:31:40','2026-04-17 19:31:40'),(16,NULL,NULL,24,1,1,1,4,'房子确实不错，如果再美团上放个团券我就买了','[]',NULL,NULL,1,'2026-04-18 10:33:34','2026-04-18 10:33:34'),(17,12,NULL,28,11,12,3,5,'张伟经纪人非常专业，服务态度很好，房子也很满意！',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(18,13,NULL,46,14,14,3,5,'刘洋经纪人经验丰富，对陆家嘴房源非常了解，推荐房源很精准。',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(19,14,NULL,66,17,16,3,4,'黄磊经纪人服务不错，房子本身也很好，就是物业费有点高。',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(20,15,NULL,76,19,19,3,5,'吴明经纪人专业素养高，深圳湾的房子环境非常好，非常满意！',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(21,16,NULL,84,21,22,3,5,'孙浩经纪人服务周到，西湖边的房子环境优美，非常满意！',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(22,18,NULL,29,12,25,3,5,'李娜经纪人非常专业，四合院很有文化底蕴，非常满意！',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(23,19,NULL,47,14,27,3,4,'刘洋经纪人服务不错，静安寺的房子位置很好，就是价格有点高。',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(24,20,NULL,67,17,30,3,4,'黄磊经纪人服务很好，房子本身也不错，就是小区有点老。',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(25,21,NULL,79,20,33,3,5,'徐娟经纪人服务周到，大梅沙的环境非常好，非常满意！',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(26,22,NULL,28,11,35,3,5,'张伟经纪人非常专业，服务态度很好，交易顺利完成。',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(27,23,NULL,26,11,10,3,5,'张伟经纪人服务非常好，阳光花园的房子采光很好，非常满意！',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(28,24,NULL,84,21,22,3,5,'孙浩经纪人服务周到，西湖边的房子环境优美，非常满意！',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(29,12,NULL,28,11,12,1,5,'阳光花园的房子非常好，采光通透，布局合理。',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(30,13,NULL,46,14,14,1,5,'陆家嘴的房子位置一流，江景壮观，装修精美。',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(31,14,NULL,66,17,16,1,4,'珠江新城的房子位置不错，就是物业费有点高。',NULL,NULL,NULL,1,'2026-04-21 19:07:51','2026-04-21 19:07:51'),(32,NULL,NULL,46,14,1,1,5,'我也觉得不错','[]',NULL,NULL,1,'2026-04-26 19:03:49','2026-04-26 19:03:49');
