--
-- Table structure for table `h_transaction`
--

DROP TABLE IF EXISTS `h_transaction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `h_transaction` (
  `transaction_id` bigint NOT NULL AUTO_INCREMENT COMMENT '交易 ID',
  `house_id` bigint NOT NULL COMMENT '房源 ID',
  `customer_id` bigint NOT NULL COMMENT '客户 ID',
  `agent_id` bigint NOT NULL COMMENT '中介 ID',
  `viewing_id` bigint DEFAULT NULL COMMENT '带看 ID',
  `transaction_no` varchar(50) DEFAULT NULL COMMENT '交易单号',
  `transaction_final_price` decimal(15,2) NOT NULL COMMENT '成交价格',
  `transaction_deposit` decimal(15,2) DEFAULT '0.00' COMMENT '定金',
  `transaction_down_payment` decimal(15,2) DEFAULT NULL COMMENT '首付',
  `transaction_payment_method` varchar(20) DEFAULT NULL COMMENT '付款方式',
  `transaction_contract_url` varchar(500) DEFAULT NULL COMMENT '合同文件 URL',
  `transaction_deal_date` date DEFAULT NULL COMMENT '成交日期',
  `transaction_status` tinyint DEFAULT '0' COMMENT '状态：0-待签约 1-已签约 2-已完成 3-已取消',
  `transaction_status_history` text COMMENT '状态变更历史',
  `transaction_remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `transaction_create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `transaction_update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`transaction_id`),
  UNIQUE KEY `transaction_no` (`transaction_no`),
  KEY `idx_house_id` (`house_id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_agent_id` (`agent_id`),
  KEY `idx_transaction_no` (`transaction_no`),
  KEY `idx_transaction_status` (`transaction_status`),
  KEY `idx_transaction_deal_date` (`transaction_deal_date`),
  KEY `viewing_id` (`viewing_id`),
  CONSTRAINT `h_transaction_ibfk_1` FOREIGN KEY (`house_id`) REFERENCES `h_house` (`house_id`) ON DELETE CASCADE,
  CONSTRAINT `h_transaction_ibfk_2` FOREIGN KEY (`customer_id`) REFERENCES `sys_customer` (`customer_id`) ON DELETE CASCADE,
  CONSTRAINT `h_transaction_ibfk_3` FOREIGN KEY (`agent_id`) REFERENCES `sys_agent` (`agent_id`) ON DELETE CASCADE,
  CONSTRAINT `h_transaction_ibfk_4` FOREIGN KEY (`viewing_id`) REFERENCES `h_viewing` (`viewing_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='交易表';
/*!40101 SET character_set_client = @saved_cs_client */;

