--
-- Table structure for table `h_viewing`
--

DROP TABLE IF EXISTS `h_viewing`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `h_viewing` (
  `viewing_id` bigint NOT NULL AUTO_INCREMENT COMMENT '带看 ID',
  `customer_id` bigint NOT NULL COMMENT '客户 ID',
  `agent_id` bigint NOT NULL COMMENT '中介 ID',
  `house_id` bigint NOT NULL COMMENT '房源 ID',
  `viewing_appoint_time` datetime NOT NULL COMMENT '预约时间',
  `viewing_actual_time` datetime DEFAULT NULL COMMENT '实际看房时间',
  `viewing_address` varchar(500) DEFAULT NULL COMMENT '看房地址',
  `viewing_status` tinyint DEFAULT '0' COMMENT '状态：0-待确认 1-已确认 2-已完成 3-已取消',
  `viewing_cancel_reason` varchar(500) DEFAULT NULL COMMENT '鍙栨秷鍘熷洜',
  `viewing_cancel_by_type` tinyint DEFAULT NULL COMMENT '鍙栨秷鎿嶄綔浜虹被鍨嬶細1-绠＄悊鍛?2-涓?粙 3-瀹㈡埛',
  `viewing_cancel_by_id` bigint DEFAULT NULL COMMENT '鍙栨秷鎿嶄綔浜?ID',
  `viewing_remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `customer_phone` varchar(20) NOT NULL COMMENT '客户电话 (快照)',
  `viewing_create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `viewing_update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`viewing_id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_agent_id` (`agent_id`),
  KEY `idx_house_id` (`house_id`),
  KEY `idx_viewing_status` (`viewing_status`),
  KEY `idx_viewing_appoint_time` (`viewing_appoint_time`),
  CONSTRAINT `h_viewing_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `sys_customer` (`customer_id`) ON DELETE CASCADE,
  CONSTRAINT `h_viewing_ibfk_2` FOREIGN KEY (`agent_id`) REFERENCES `sys_agent` (`agent_id`) ON DELETE CASCADE,
  CONSTRAINT `h_viewing_ibfk_3` FOREIGN KEY (`house_id`) REFERENCES `h_house` (`house_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='带看记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

