DROP TABLE IF EXISTS `sys_admin`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_admin` (
  `admin_id` bigint NOT NULL AUTO_INCREMENT COMMENT '管理员 ID',
  `admin_password` varchar(200) NOT NULL COMMENT '密码 (BCrypt 加密)',
  `admin_name` varchar(50) NOT NULL DEFAULT 'admin' COMMENT '管理员名称',
  `admin_email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `admin_phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `admin_avatar` varchar(500) DEFAULT NULL COMMENT '头像 URL',
  `admin_create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `admin_update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`admin_id`),
  KEY `idx_admin_name` (`admin_name`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='管理员表';
/*!40101 SET character_set_client = @saved_cs_client */;

