--
-- Table structure for table `sys_customer`
--

DROP TABLE IF EXISTS `sys_customer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_customer` (
  `customer_id` bigint NOT NULL AUTO_INCREMENT COMMENT '客户 ID',
  `customer_password` varchar(200) NOT NULL COMMENT '密码 (BCrypt 加密)',
  `customer_nickname` varchar(50) DEFAULT NULL COMMENT '真实姓名',
  `customer_phone` varchar(20) NOT NULL COMMENT '手机号 (AES 加密)',
  `customer_email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `customer_gender` tinyint DEFAULT NULL COMMENT '性别：0-未知 1-男 2-女',
  `customer_avatar` varchar(500) DEFAULT NULL COMMENT '头像 URL',
  `customer_status` tinyint DEFAULT '1' COMMENT '状态：0-禁用 1-正常',
  `customer_create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `customer_update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`customer_id`),
  KEY `idx_customer_status` (`customer_status`),
  KEY `idx_customer_phone` (`customer_phone`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='客户表';
/*!40101 SET character_set_client = @saved_cs_client */;

